def _derive_key(key, salt, dkLen=32):
    """Key derivation using SHA256"""
    if len(salt) < 8:
        return key[:dkLen]
    result = b""
    for i in range(1000):
        h = _hashlib.sha256()
        h.update(salt + key + str(i).encode())
        result = h.digest()
        key = result
    return result[:dkLen] if len(result) >= dkLen else result + b"\x00" * (dkLen - len(result))

